#include <bits/stdc++.h>
using namespace std;

const int MAXNODES = 10000;
const int MAXEDGES = 2000000;
const int INF = 0x3f3f3f3f;

int total_nodes, total_edges, max_flow, total_cost;

struct Edge
{
    int to, next, capacity, flow, cost;
} edges[MAXEDGES];
int head[MAXNODES], edge_idx;
int parent[MAXNODES], dist[MAXNODES];
bool in_queue[MAXNODES];

void init_graph(int n)
{
    total_nodes = n;
    edge_idx = 0;
    memset(head, -1, sizeof(head));
}
void add_edge(int u, int v, int cap, int cst)
{
    edges[edge_idx].to = v;
    edges[edge_idx].capacity = cap;
    edges[edge_idx].cost = cst;
    edges[edge_idx].flow = 0;
    edges[edge_idx].next = head[u];
    head[u] = edge_idx++;
    edges[edge_idx].to = u;
    edges[edge_idx].capacity = 0;
    edges[edge_idx].cost = -cst;
    edges[edge_idx].flow = 0;
    edges[edge_idx].next = head[v];
    head[v] = edge_idx++;
}
bool bellman_ford(int s, int t)
{
    queue<int> q;
    for (int i = 0; i < total_nodes; i++)
    {
        dist[i] = INF;
        in_queue[i] = false;
        parent[i] = -1;
    }
    dist[s] = 0;
    in_queue[s] = true;
    q.push(s);
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        in_queue[u] = false;
        for (int i = head[u]; i != -1; i = edges[i].next)
        {
            int v = edges[i].to;
            if (edges[i].capacity > edges[i].flow && dist[v] > dist[u] + edges[i].cost)
            {
                dist[v] = dist[u] + edges[i].cost;
                parent[v] = i;
                if (!in_queue[v])
                {
                    in_queue[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return parent[t] != -1;
}
int min_cost_max_flow(int s, int t, int &total_cost)
{
    int flow = 0;
    total_cost = 0;
    while (bellman_ford(s, t))
    {
        int push_flow = INF;
        for (int i = parent[t]; i != -1; i = parent[edges[i ^ 1].to])
        {
            if (push_flow > edges[i].capacity - edges[i].flow)
                push_flow = edges[i].capacity - edges[i].flow;
        }
        for (int i = parent[t]; i != -1; i = parent[edges[i ^ 1].to])
        {
            edges[i].flow += push_flow;
            edges[i ^ 1].flow -= push_flow;
            total_cost += edges[i].cost * push_flow;
        }
        flow += push_flow;
    }
    return flow;
}

int main()
{
    cin >> n >> m >> k >> c >> d;
    init_graph(MAXNODES);
    for(int i = 0; i < k; i++)
    {
        int x;
        cin >> x;
        add_edge(0, x, 1, 0);
    }
    for(int i = 0; i < 100; i++)
    {
        for(int j = 0; j < k; j++)
            add_edge(1+i*n, 9999, 1, i*c);
    }
    for(int i = 0; i < m; i++)
    {
        int u, v;
        cin >> u >> v;
        for(int j = 1; j < 100; j++)
        {
            for(int gg = 1; gg <= k; gg++)
            {
                add_edge(u+(j-1)*n, v+j*n, 1, (2*gg-1)*d);
                add_edge(v+(j-1)*n, u+j*n, 1, (2*gg-1)*d);
            }
        }
    }
    for(int i = 1; i <= n; i++)
    {
        for(int j = 1; j < 100; j++)
        {
            add_edge(i+(j-1)*n, i+j*n, k, 0);
        }
    }

    int total_cost_output;
    min_cost_max_flow(0, 9999, total_cost_output);
    cout << total_cost_output << endl;
}
